export default function MenuCard({ item, addToCart }) {
  const outOfStock = item.stock <= 0;

  return (
    <div className="menu-card">
      <h3>{item.name}</h3>
      <p>₹{item.price}</p>
      <p>
        Stock: {item.stock > 0 ? item.stock : "Out of stock"}
      </p>

      <button
        disabled={outOfStock}
        onClick={() => addToCart(item)}
      >
        {outOfStock ? "Out of Stock" : "Add to Cart"}
      </button>
    </div>
  );
}
